import XCTest
@testable import TodoTrackerKit

/// tests/fixtures/board-moves.json (generated by the C# core's BoardMovesFixtureTests): cards move between the Board's
/// columns, and tasks in the Tasks outline, exactly as the server moves them.
final class BoardMovesFixtureTests: XCTestCase {
    private func fixture() throws -> [String: Any] {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { root.deleteLastPathComponent() }
        let data = try Data(contentsOf: root.appendingPathComponent("tests/fixtures/board-moves.json"))
        return try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    func testCardsAndTasksMoveLikeTheServerMovesThem() throws {
        let cases = try fixture()["cases"] as? [[String: Any]] ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 8)
        let t0 = BoardCodec.parseDate("2026-01-05T09:00:00Z")!
        for test in cases {
            let name = test["name"] as? String ?? "?"
            let board = TaskBoard()
            board.timeZone = TimeZone(identifier: "UTC")!
            var tasks: [String: WorkItem] = [:]
            for (n, step) in (test["steps"] as? [[String: Any]] ?? []).enumerated() {
                let at = t0.addingTimeInterval(Double(n) * 60)
                let what = "\(name), step \(n + 1) (\(step["do"] as? String ?? "?"))"
                if step["do"] as? String == "check" {
                    check(board, tasks, step, at: at, what)
                    continue
                }
                let fails = step["fails"] as? Bool ?? false
                do {
                    try run(step, board, &tasks, at: at)
                    XCTAssertFalse(fails, "\(what) should have been refused")
                } catch {
                    XCTAssertTrue(fails, "\(what) failed: \(error)")
                }
            }
        }
    }

    private func run(_ step: [String: Any], _ board: TaskBoard, _ tasks: inout [String: WorkItem], at: Date) throws {
        func task(_ field: String = "task") throws -> UUID { try XCTUnwrap(tasks[step[field] as? String ?? ""]).id }
        let group = (step["group"] as? String).flatMap { name in board.groups.first { $0.name == name }?.id }
        switch step["do"] as? String {
        case "add":
            let item = try board.addTask(NewTask(step["title"] as! String, parentId: (step["parent"] as? String).flatMap { tasks[$0]?.id },
                                                 groupId: group, stage: (step["stage"] as? String).flatMap(Stage.init(rawValue:))), now: at)
            if let rule = step["repeat"] as? String { try board.update(item.id, TaskChanges(repeatRule: rule), now: at) }
            tasks[step["key"] as! String] = item
        case "stage": try board.apply(.stage(task(), Stage(rawValue: step["stage"] as! String)!), now: at)
        case "complete": try board.apply(.complete(task()), now: at)
        case "reopen": try board.reopen(task(), now: at)
        case "archive": try board.archive(task(), now: at)
        case "timer": _ = try board.startTimer(task(), now: at)
        case "reorder": try board.apply(.reorder(task(), before: (step["before"] as? String).flatMap { tasks[$0]?.id }), now: at)
        case "reorderAfter": try board.apply(.reorderAfter(task(), after: task("after")), now: at)
        case "move":
            try board.apply(.move(task(), parentId: (step["parent"] as? String).flatMap { tasks[$0]?.id }, groupId: group, index: step["index"] as? Int), now: at)
        case "indent", "outdent":
            let id = try task()
            guard let moves = step["do"] as? String == "indent" ? OutlineMoves.indent(board, id) : OutlineMoves.outdent(board, id) else {
                throw BoardError.conflict("Can't move it there.")
            }
            for move in moves { try board.apply(move, now: at) }
        default:
            XCTFail("unknown step \(step)")
        }
    }

    private func check(_ board: TaskBoard, _ tasks: [String: WorkItem], _ step: [String: Any], at: Date, _ what: String) {
        let keys = Dictionary(uniqueKeysWithValues: tasks.map { ($0.value.id, $0.key) })
        func key(_ item: WorkItem) -> String { keys[item.id] ?? "?" }
        var tree: [String] = []
        func walk(_ item: WorkItem, _ depth: Int) {
            tree.append(String(repeating: "  ", count: depth) + key(item))
            item.children.forEach { walk($0, depth + 1) }
        }
        board.items.forEach { walk($0, 0) }
        XCTAssertEqual(tree, step["tree"] as? [String], "\(what): tree")
        var groups: [String: String] = [:]
        for root in board.items { groups[key(root)] = board.groups.first { $0.id == root.groupId }?.name }
        XCTAssertEqual(groups, step["groups"] as? [String: String], "\(what): groups")
        let columns = BoardColumns.of(board.items, now: at)
        for column in BoardColumn.allCases {
            XCTAssertEqual(columns[column]?.map(key), (step["columns"] as? [String: [String]])?[column.rawValue], "\(what): \(column.name)")
        }
        XCTAssertEqual(board.allItems.filter(\.isDone).map(key), step["done"] as? [String], "\(what): done")
        XCTAssertEqual(board.items.filter { $0.archivedAt != nil }.map(key), step["archived"] as? [String], "\(what): archived")
    }
}
